#define _GNU_SOURCE
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <dlfcn.h>

/* Injected malloc/calloc/realloc that fail once a cumulative budget is
 * exhausted, to simulate out-of-memory conditions deterministically. */

static long budget = -1;   /* total bytes allowed; -1 = unlimited */
static long used = 0;      /* bytes currently handed out (not tracked precisely) */
static int  fail_ge = -1;  /* fail allocations with size >= this */
static int  fail_after = -1; /* fail after this many successful allocations */
static int  nalloc = 0;

static void *(*real_malloc)(size_t);
static void *(*real_calloc)(size_t, size_t);
static void *(*real_realloc)(void *, size_t);
static void (*real_free)(void *);

static void init(void) {
  static int done = 0;
  if (done) return;
  done = 1;
  const char *b = getenv("OOM_BUDGET");
  const char *g = getenv("OOM_FAIL_GE");
  const char *a = getenv("OOM_FAIL_AFTER");
  const char *mode = getenv("OOM_MODE");
  real_malloc = dlsym(RTLD_NEXT, "malloc");
  real_calloc = dlsym(RTLD_NEXT, "calloc");
  real_realloc = dlsym(RTLD_NEXT, "realloc");
  real_free = dlsym(RTLD_NEXT, "free");
  if (b) budget = atol(b);
  if (g) fail_ge = atoi(g);
  if (a) fail_after = atoi(a);
  (void)mode;
}

void *malloc(size_t size) {
  init();
  if (fail_ge >= 0 && (long)size >= fail_ge) return NULL;
  if (fail_after >= 0 && nalloc++ >= fail_after) return NULL;
  if (budget >= 0 && used + (long)size > budget) return NULL;
  void *p = real_malloc(size);
  if (p && budget >= 0) used += (long)size;
  return p;
}

void *calloc(size_t nmemb, size_t size) {
  init();
  size_t total = nmemb * size;
  if (nmemb && (total / nmemb) != size) return NULL; /* overflow */
  if (fail_ge >= 0 && (long)total >= fail_ge) return NULL;
  if (fail_after >= 0 && nalloc++ >= fail_after) return NULL;
  if (budget >= 0 && used + (long)total > budget) return NULL;
  void *p = real_calloc(nmemb, size);
  if (p && budget >= 0) used += (long)total;
  return p;
}

void *realloc(void *ptr, size_t size) {
  init();
  if (fail_ge >= 0 && (long)size >= fail_ge) return NULL;
  if (fail_after >= 0 && nalloc++ >= fail_after) return NULL;
  if (budget >= 0 && used + (long)size > budget) return NULL;
  /* best-effort budget tracking: don't subtract old size */
  void *p = real_realloc(ptr, size);
  if (p && budget >= 0) used += (long)size;
  return p;
}

void free(void *ptr) {
  init();
  real_free(ptr);
}

